# Karachi Runner sound maker
# Author: Mashhood Ali
#
# Every sound effect in this game is generated by this script:
# short original sine sweeps and noise bursts, written as WAV
# files. Nothing is sampled, downloaded or copied, so there are
# no third party rights on these files at all.
#
# Run it from the project folder:
#     python tools/make_sounds.py
# It writes the WAV files into assets/audio/.

import math
import os
import random
import struct
import wave

SAMPLE_RATE = 22050
OUT_DIR = os.path.join(os.path.dirname(__file__), "..", "assets", "audio")


def save_wav(name, samples):
    path = os.path.join(OUT_DIR, name)
    frames = b"".join(
        struct.pack("<h", max(-32767, min(32767, int(s * 32767))))
        for s in samples
    )
    with wave.open(path, "wb") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(SAMPLE_RATE)
        w.writeframes(frames)
    print("wrote", path)


def sweep(freq_from, freq_to, seconds, volume=0.5):
    """A sine tone gliding from one frequency to another."""
    count = int(SAMPLE_RATE * seconds)
    out = []
    for i in range(count):
        t = i / SAMPLE_RATE
        frac = i / count
        freq = freq_from + (freq_to - freq_from) * frac
        env = 1.0 - frac * 0.6
        out.append(math.sin(2 * math.pi * freq * t) * volume * env)
    return out


def tone(freq, seconds, volume=0.5, decay=True):
    count = int(SAMPLE_RATE * seconds)
    out = []
    for i in range(count):
        frac = i / count
        env = (1.0 - frac) if decay else 1.0
        out.append(math.sin(2 * math.pi * freq * i / SAMPLE_RATE) * volume * env)
    return out


def jump():
    # Quick up-chirp: the runner leaves the ground
    return sweep(300, 900, 0.18)


def coin():
    # Classic two-tone ding: low note, then a longer high note
    return tone(900, 0.07, 0.45, decay=False) + tone(1350, 0.16, 0.45)


def hit():
    # A low thud with a little noise in it
    base = tone(110, 0.22, 0.7)
    return [s + random.uniform(-0.12, 0.12) * (1.0 - i / len(base))
            for i, s in enumerate(base)]


def click():
    # One short tick for menu keys
    return tone(2000, 0.03, 0.35, decay=False)


def smash():
    # A noise burst, smoothed a little, over a low body thump
    count = int(SAMPLE_RATE * 0.25)
    raw = [random.uniform(-1, 1) for _ in range(count)]
    smooth = []
    for i in range(count):
        part = raw[max(0, i - 2):i + 3]
        smooth.append(sum(part) / len(part))
    out = []
    for i in range(count):
        frac = i / count
        thump = math.sin(2 * math.pi * 90 * i / SAMPLE_RATE)
        out.append((smooth[i] * 0.6 + thump * 0.4) * (1.0 - frac) * 0.8)
    return out


def game_over():
    # Four descending tones: the run is over
    out = []
    for freq in (600, 450, 320, 220):
        out += tone(freq, 0.15, 0.45)
    return out


def main():
    os.makedirs(OUT_DIR, exist_ok=True)
    random.seed(1420)  # same sounds on every run of the script
    save_wav("jump.wav", jump())
    save_wav("coin.wav", coin())
    save_wav("hit.wav", hit())
    save_wav("click.wav", click())
    save_wav("smash.wav", smash())
    save_wav("gameover.wav", game_over())


if __name__ == "__main__":
    main()
